bearer_token = "6e6fee6f536cf8a907b52c7d897e9a55"
p.headers = {
    "Authorization": "Bearer %s" % bearer_token,
    "Content-Type": "application/json"
}
def safe_string(val):
    if val is None:
        return ''
    try:
        return unicode(val)
    except:
        try:
            return str(val)
        except:
            return ''
def jescape(s):
    if s is None:
        s = ""
    try:
        s = str(s)
    except:
        s = ""
    s = s.replace("\\", "\\\\")
    s = s.replace('"', '\\"')
    s = s.replace("\r", "\\r").replace("\n", "\\n").replace("\t", "\\t")
    return s
questions_json = []
responses_json = []
payload_labels = []
num_non_empty = 0
for label in p.alias_client_dict['question_labels']:
    q = allQuestions[label]
    val = safe_string(q.response.val)
    p.alias_client_dict['responses'][label] = val
    p.alias_client_dict['questions'][label] = label
    # ONLY send non-empty responses
    if val.strip():
        questions_json.append('"%s"' % jescape(label))
        responses_json.append('"%s"' % jescape(val))
        payload_labels.append(label)
        num_non_empty += 1
p.alias_client_dict['payload_labels'] = payload_labels
p.alias_client_dict['num_non_empty'] = num_non_empty
# Read keystroke payload from hidden field
